using System.IO;using System.IO.Compression;using System.Reflection;using System.Text.Json;using Microsoft.Data.Sqlite;namespace Produktionsplanung.App.Services;
public static class BackupService{private static readonly JsonSerializerOptions JsonOptions=new(){WriteIndented=true};public static string CreateBackup(string targetPath,AppSettings settings){AppPaths.EnsureDirectories();if(!File.Exists(AppPaths.DatabasePath))throw new InvalidOperationException("Die OpsCompact-Datenbank wurde nicht gefunden.");if(!Path.IsPathRooted(targetPath))targetPath=Path.Combine(AppPaths.RootDirectory,targetPath);if(!targetPath.EndsWith(".kpibackup",StringComparison.OrdinalIgnoreCase))targetPath+=".kpibackup";var targetDirectory=Path.GetDirectoryName(targetPath);if(!string.IsNullOrWhiteSpace(targetDirectory))Directory.CreateDirectory(targetDirectory);var temp=Path.Combine(Path.GetTempPath(),$"opscompact-backup-{Guid.NewGuid():N}");Directory.CreateDirectory(temp);try{var snapshot=Path.Combine(temp,"produktionsplanung.db");CreateDatabaseSnapshot(snapshot);File.WriteAllText(Path.Combine(temp,"settings.json"),JsonSerializer.Serialize(settings,JsonOptions));var manifest=new BackupManifest{Product="OpsCompact",CreatedAtLocal=DateTime.Now,AppVersion=Assembly.GetExecutingAssembly().GetName().Version?.ToString()??"unknown",DatabaseFile="produktionsplanung.db",SettingsFile="settings.json"};File.WriteAllText(Path.Combine(temp,"manifest.json"),JsonSerializer.Serialize(manifest,JsonOptions));if(File.Exists(targetPath))File.Delete(targetPath);ZipFile.CreateFromDirectory(temp,targetPath,CompressionLevel.Optimal,false);settings.LastSuccessfulBackupAtLocal=DateTime.Now;settings.LastSuccessfulBackupPath=AppPaths.IsPortableMode?AppSettingsService.ToStoredStoragePath(targetPath,"Backups"):targetPath;AppSettingsService.Save(settings);return targetPath;}finally{TryDeleteDirectory(temp);}}
 public static string CreateAutomaticBackup(AppSettings settings){var directory=AppSettingsService.ResolveStoragePath(settings.DefaultBackupDirectory,"Backups");Directory.CreateDirectory(directory);var path=Path.Combine(directory,$"OpsCompact-auto-{DateTime.Now:yyyyMMdd-HHmmss}.kpibackup");var created=CreateBackup(path,settings);PruneAutomaticBackups(directory,settings.BackupRetentionCount);return created;}
 public static void RestoreBackup(string backupPath){if(!File.Exists(backupPath))throw new FileNotFoundException("Die ausgewählte Backup-Datei wurde nicht gefunden.",backupPath);var temp=Path.Combine(Path.GetTempPath(),$"opscompact-restore-{Guid.NewGuid():N}");Directory.CreateDirectory(temp);try{ZipFile.ExtractToDirectory(backupPath,temp,true);var db=Path.Combine(temp,"produktionsplanung.db");if(!File.Exists(db))throw new InvalidDataException("Das Backup enthält keine OpsCompact-Datenbank.");ValidateDatabase(db);var sp=Path.Combine(temp,"settings.json");if(File.Exists(sp)){_ =JsonSerializer.Deserialize<AppSettings>(File.ReadAllText(sp))??throw new InvalidDataException("Die Einstellungen im Backup sind ungültig.");}AppPaths.EnsureDirectories();SqliteConnection.ClearAllPools();File.Copy(db,AppPaths.DatabasePath,true);SessionService.InvalidateAfterRestore();if(File.Exists(sp))File.Copy(sp,AppPaths.SettingsPath,true);}finally{TryDeleteDirectory(temp);}}
 private static void CreateDatabaseSnapshot(string dest){var sb=new SqliteConnectionStringBuilder{DataSource=AppPaths.DatabasePath,Mode=SqliteOpenMode.ReadWrite,Pooling=false};var db=new SqliteConnectionStringBuilder{DataSource=dest,Mode=SqliteOpenMode.ReadWriteCreate,Pooling=false};using var s=new SqliteConnection(sb.ConnectionString);using var d=new SqliteConnection(db.ConnectionString);s.Open();d.Open();s.BackupDatabase(d);}private static void ValidateDatabase(string path){var b=new SqliteConnectionStringBuilder{DataSource=path,Mode=SqliteOpenMode.ReadOnly,Pooling=false};using var c=new SqliteConnection(b.ConnectionString);c.Open();using var cmd=c.CreateCommand();cmd.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name IN ('Employees','ProductionOrders');";if(Convert.ToInt32(cmd.ExecuteScalar())<2)throw new InvalidDataException("Die Datei ist kein gültiges OpsCompact-Backup.");}private static void PruneAutomaticBackups(string directory,int count){count=Math.Clamp(count,1,100);foreach(var f in new DirectoryInfo(directory).GetFiles("*.kpibackup").Where(x=>x.Name.StartsWith("OpsCompact-auto-",StringComparison.OrdinalIgnoreCase)||x.Name.StartsWith("KPI-rai-auto-",StringComparison.OrdinalIgnoreCase)).OrderByDescending(x=>x.CreationTimeUtc).Skip(count)){try{f.Delete();}catch{}}}private static void TryDeleteDirectory(string path){try{if(Directory.Exists(path))Directory.Delete(path,true);}catch{}}}
public sealed class BackupManifest{public string Product{get;set;}="";public DateTime CreatedAtLocal{get;set;}public string AppVersion{get;set;}="";public string DatabaseFile{get;set;}="";public string SettingsFile{get;set;}="";}
